-- Migration: 020_recommendations
-- Created: 2026-05-21
-- Per-user recommendations generated by the recommendation engine

DO $$ BEGIN
    CREATE TYPE recommendation_strategy AS ENUM (
        'VIEWED_TOGETHER',
        'SIMILAR_USERS',
        'TRENDING'
    );
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

CREATE TABLE IF NOT EXISTS public.recommendations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    customer_id UUID NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
    tracked_user_id UUID NOT NULL REFERENCES tracked_users(id) ON DELETE CASCADE,
    strategy recommendation_strategy NOT NULL,
    item_ids UUID[] NOT NULL DEFAULT '{}',
    generated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    expires_at TIMESTAMP WITH TIME ZONE DEFAULT (NOW() + INTERVAL '24 hours'),
    UNIQUE(customer_id, tracked_user_id, strategy)
);

CREATE INDEX IF NOT EXISTS idx_recommendations_user ON recommendations(tracked_user_id, strategy);
CREATE INDEX IF NOT EXISTS idx_recommendations_expires ON recommendations(expires_at) WHERE expires_at < NOW();

ALTER TABLE public.recommendations ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Customers can read recommendations" ON public.recommendations;
CREATE POLICY "Customers can read recommendations"
    ON public.recommendations FOR SELECT
    USING (customer_id = auth.uid());

DROP POLICY IF EXISTS "Customers can insert recommendations" ON public.recommendations;
CREATE POLICY "Customers can insert recommendations"
    ON public.recommendations FOR INSERT
    WITH CHECK (customer_id = auth.uid());

DROP POLICY IF EXISTS "Customers can update recommendations" ON public.recommendations;
CREATE POLICY "Customers can update recommendations"
    ON public.recommendations FOR UPDATE
    USING (customer_id = auth.uid());

DROP POLICY IF EXISTS "Customers can delete recommendations" ON public.recommendations;
CREATE POLICY "Customers can delete recommendations"
    ON public.recommendations FOR DELETE
    USING (customer_id = auth.uid());
